'use strict';
// Subscribers & plans: netops' own RADIUS (replacing ISPman). Who may log in, at what speed and until when.
const radiusView={tab:'subscribers',q:'',filter:'all',data:null,request:0};
const ksh=n=>'KSh '+Number(n||0).toLocaleString();
const durationText=p=>p.durationValue+' '+(p.durationValue===1?p.durationUnit.replace(/s$/,''):p.durationUnit);
const expiryText=s=>s.expiresAt==null?'No expiry':stamp(s.expiresAt);
const stateBadge=s=>`<span class="status ${s.state==='active'?'online':s.state==='expired'||s.state==='unpaid'?'warning':'offline'}" ${s.deactivatedReason?`title="${h(s.deactivatedReason)}"`:''}>${{active:'Active',expired:'Expired',unpaid:'Never paid',suspended:'Deactivated'}[s.state]||h(s.state)}</span>${s.online&&(s.state==='expired'||s.state==='unpaid')?'<small>online while expired</small>':''}${s.installFeeDue>0?`<small>install fee due KSh ${s.installFeeDue}</small>`:''}`;
const bytesShort=n=>{const u=['B','KB','MB','GB','TB'];let i=0;n=Number(n)||0;while(n>=1024&&i<u.length-1){n/=1024;i++;}return (n>=10||i===0?Math.round(n):n.toFixed(1))+' '+u[i];};
function radiusForm(title,description,fields,submitLabel,onSubmit){
 $('#editor-title').textContent=title;$('#editor-description').textContent=description;$('#editor-fields').innerHTML=fields;$('#editor-error').textContent='';$('#editor-form [type=submit]').textContent=submitLabel;
 $('#editor-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=$('[type=submit]',form);button.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(form)));$('#editor').close();await loadRadius();}catch(error){$('#editor-error').textContent=error.message;}finally{button.disabled=false;}};
 $('#editor').showModal();
}
const radiusField=(label,input)=>`<label>${label}${input}</label>`;
const radiusOptions=(values,current)=>values.map(([v,l])=>`<option value="${h(v)}" ${String(current)===String(v)?'selected':''}>${h(l)}</option>`).join('');
function planEditor(id){const p=radiusView.data.plans.find(x=>x.id===id)||{service:'pppoe',durationValue:30,durationUnit:'days',devices:1,active:true};
 radiusForm(id?'Edit plan':'New plan','Speed, price and how long one payment lasts. Changes apply at each customer\'s next login.',
  radiusField('Plan name',`<input name="name" required maxlength="120" value="${h(p.name||'')}" placeholder="Home 10 Mbps">`)+
  `<div class="form-grid">${radiusField('For',`<select name="service">${radiusOptions([['pppoe','PPPoE'],['hotspot','Hotspot'],['both','PPPoE and Hotspot']],p.service)}</select>`)+radiusField('Price (KSh)',`<input name="price" type="number" min="0" step="1" required value="${h(p.price??'')}">`)+
  radiusField('Download (Mbps)',`<input name="downloadMbps" type="number" min="0.064" step="0.001" required value="${h(p.downloadMbps??'')}">`)+radiusField('Upload (Mbps)',`<input name="uploadMbps" type="number" min="0.064" step="0.001" required value="${h(p.uploadMbps??'')}">`)+
  radiusField('Lasts',`<input name="durationValue" type="number" min="1" max="1000" required value="${h(p.durationValue)}">`)+radiusField('Unit',`<select name="durationUnit">${radiusOptions([['hours','Hours'],['days','Days'],['weeks','Weeks'],['months','Months (30 days)']],p.durationUnit)}</select>`)+
  radiusField('Devices at once (hotspot)',`<input name="devices" type="number" min="1" max="50" value="${h(p.devices)}">`)}</div>`+
  radiusField('Description (optional)',`<input name="description" maxlength="500" value="${h(p.description||'')}">`),
  id?'Save plan':'Create plan',input=>api(id?'radius/plans/'+id:'radius/plans',id?'PATCH':'POST',input));}
function subscriberEditor(id){const d=radiusView.data,s=d.subscribers.find(x=>x.id===id)||{service:'pppoe',status:'active'};
 if(!d.plans.length){toast('Create a plan first');radiusView.tab='plans';paintRadius();return;}
 const expiry=s.expiresAt?new Date(s.expiresAt-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'';
 radiusForm(id?'Edit subscriber':'New subscriber',id?'Leave the password empty to keep the current one.':'Leave the password empty to generate one. Without an expiry date the customer starts expired; use Renew once they pay.',
  `<div class="form-grid">${radiusField('Customer name',`<input name="name" required maxlength="120" value="${h(s.name||'')}">`)+radiusField('Phone',`<input name="phone" maxlength="30" value="${h(s.phone||'')}" placeholder="07…">`)+
  radiusField('Username',`<input name="username" required maxlength="64" pattern="[A-Za-z0-9._\\-]{2,64}" value="${h(s.username||'')}" autocomplete="off">`)+radiusField(id?'New password (optional)':'Password (optional)',`<input name="password" maxlength="64" autocomplete="new-password">`)+
  radiusField('Connection',`<select name="service" id="sub-service">${radiusOptions([['pppoe','PPPoE'],['hotspot','Hotspot'],['static','Static IP']],s.service)}</select>`)+`<label>Router${(state.session.user.routerScope||[]).length?'':' (optional; required for static IP)'}<select name="routerId">${(state.session.user.routerScope||[]).length?'':'<option value="">—</option>'}${rows('devices').filter(d=>d.type==='router'&&(!(state.session.user.routerScope||[]).length||state.session.user.routerScope.includes(d.id))).map(r=>`<option value="${h(r.id)}" ${s.routerId===r.id?'selected':''}>${h(r.name)}</option>`).join('')}</select></label><label data-static ${s.service==='static'?'':'hidden'}>Customer MAC (optional, for ARP pinning)<input name="mac" maxlength="17" value="${h(s.staticMac||'')}" placeholder="AA:BB:CC:DD:EE:FF"></label>`+radiusField('Plan',`<select name="planId" required>${radiusOptions(d.plans.map(p=>[p.id,p.name+' · '+ksh(p.price)]),s.planId)}</select>`)+
  radiusField('Expires',`<input name="expiresAt" type="datetime-local" value="${expiry}">`)+radiusField('Status',`<select name="status">${radiusOptions([['active','Active'],['suspended','Suspended']],s.status)}</select>`)+
  radiusField('Static IP (optional)',`<input name="staticIp" maxlength="45" value="${h(s.staticIp||'')}" placeholder="10.40.0.50">`)+radiusField('Devices at once (blank = package)',`<input name="maxDevices" type="number" min="1" max="50" value="${h(s.maxDevices??'')}">`)+(id?'':radiusField('Installation fee KSh (blank = default, 0 = waive)',`<input name="installFee" type="number" min="0" step="1">`))+radiusField('Email (optional)',`<input name="email" type="email" maxlength="120" value="${h(s.email||'')}">`)+(s.service==='pppoe'?radiusField('Bound router MAC',`<input name="boundMac" maxlength="17" value="${h(s.boundMac||'')}" placeholder="Empty = not bound">`):'')}</div>`+
  `<div class="form-grid">${radiusField('Address / directions',`<input name="address" maxlength="250" value="${h(s.address||'')}" placeholder="Estate, building, landmark">`)+radiusField('Map latitude',`<input name="latitude" type="number" step="0.000001" min="-90" max="90" value="${s.latitude??''}" placeholder="-1.2186">`)+radiusField('Map longitude',`<input name="longitude" type="number" step="0.000001" min="-180" max="180" value="${s.longitude??''}" placeholder="36.9230">`)+radiusField('Referred by (username)',`<input name="referredBy" maxlength="64" value="${h(s.referredBy||'')}">`)+radiusField('Roaming',`<select name="roaming">${radiusOptions([['','ISP setting'],['any','Any router'],['assigned','Only their router']],s.roaming||'')}</select>`)}</div>`+
  radiusField('Notes (optional)',`<input name="notes" maxlength="1000" value="${h(s.notes||'')}">`),
  id?'Save subscriber':'Create subscriber',async input=>{input.expiresAt=input.expiresAt?new Date(input.expiresAt).getTime():'';const saved=await api(id?'radius/subscribers/'+id:'radius/subscribers',id?'PATCH':'POST',input);if(saved.password)setTimeout(()=>showDetails('Login details — '+saved.name,`<p>Give these to the customer. The password is shown once here; admins can reveal it later.</p><dl class="radius-credentials"><dt>Username</dt><dd><code>${h(saved.username)}</code></dd><dt>Password</dt><dd><code>${h(saved.password)}</code></dd></dl><p class="muted">While testing alongside ISPman, the customer logs in as <code>${h(saved.username)}@${h(radiusView.data.settings.realm)}</code>.</p>`),50);});
 const sv=$('#sub-service');if(sv)sv.onchange=()=>{for(const el of document.querySelectorAll('#editor [data-static]'))el.hidden=sv.value!=='static';};}
async function renewSubscriber(id){const s=radiusView.data.subscribers.find(x=>x.id===id),p=radiusView.data.plans.find(x=>x.id===s?.planId);if(!s||!p)return;
 radiusForm('Renew '+s.name,`Adds ${durationText(p)} per period from ${s.state==='active'&&s.expiresAt?'the current expiry':'now'}. Record the payment under Billing records.`,radiusField('Periods',`<input name="periods" type="number" min="1" max="24" value="1">`)+`<p class="muted">Plan: ${h(p.name)} · ${ksh(p.price)} per period</p>`,'Renew',input=>api('radius/subscribers/'+id+'/renew','POST',{periods:Number(input.periods)}));}
async function revealPassword(id){try{const r=await api('radius/subscribers/'+id+'/password');showDetails('Password',`<p><code>${h(r.password||'—')}</code></p>`);}catch(error){toast(error.message);}}
async function removeRecord(kind,id,label){if(!confirm('Delete '+label+'? This cannot be undone.'))return;try{await api('radius/'+kind+'/'+id,'DELETE');await loadRadius();}catch(error){toast(error.message);}}
function paintRadius(){const d=radiusView.data;if(!d)return;
 $('#radius-metrics').innerHTML=[['Subscribers',d.counts.subscribers,'In the netops RADIUS'],['Active',d.counts.active,'Paid up and allowed online'],['Online now',d.counts.online,'Sessions reported by the routers'],['Expiring in 3 days',d.counts.expiringSoon,'Remind these customers'],['Expired',d.counts.expired,'PPPoE is restricted, hotspot rejected']].map(([t,v,p])=>`<div class="card metric-card"><div><div class="metric-title">${t}</div><div class="metric-value">${Number(v).toLocaleString()}</div><p>${p}</p></div></div>`).join('');
 const q=radiusView.q.toLowerCase(),match=(...v)=>!q||v.join(' ').toLowerCase().includes(q);
 const subs=d.subscribers.filter(s=>(!radiusView.pred||radiusView.pred(s))&&(radiusView.filter==='all'||s.state===radiusView.filter||(radiusView.filter==='online'&&s.online))&&match(s.name,s.username,s.phone,s.planName,s.lastMac,s.staticIp));
 $('#radius-subscribers').innerHTML=table(['CUSTOMER','USERNAME','PLAN','STATUS','EXPIRES','LAST SEEN','ACTIONS'],subs,s=>`<tr><td><strong>${h(s.name)}</strong><small>${h([s.phone,s.service==='hotspot'?'Hotspot':'PPPoE'].filter(Boolean).join(' · '))}</small></td><td><code>${h(s.username)}</code>${s.online?'<small class="radius-online">● online</small>':''}</td><td>${h(s.planName)}</td><td>${stateBadge(s)}</td><td>${h(expiryText(s))}${s.balance?`<small>Credit ${ksh(s.balance)}</small>`:''}</td><td>${s.lastSeen?h(stamp(s.lastSeen)):'<span class="muted">Never</span>'}<small>${h(s.lastMac||'')}</small></td><td class="radius-actions"><button class="button primary" data-pay="${s.id}">Payment</button><button class="button secondary" data-renew="${s.id}">Renew</button><button class="button ghost" data-edit-sub="${s.id}">Edit</button><button class="button ghost" data-pass="${s.id}">Password</button><button class="button ghost" data-del-sub="${s.id}">Delete</button></td></tr>`,d.subscribers.length?'No subscribers match.':'No subscribers yet. Add your first, or import them from ISPman later.');
 {const ordered=d.plans.filter(p=>!radiusView.planPred||radiusView.planPred(p)).sort((a,b)=>(a.order||0)-(b.order||0)||a.price-b.price),tags=p=>{const r=[];const w=p.window||{};if(p.popular)r.push(['Popular','online']);if(p.active===false)r.push(['Off sale','offline']);if(p.hidden)r.push(['Hidden','warning']);if(p.burst?.enabled)r.push(['Burst','']);if(p.fup?.enabled)r.push(['FUP','']);if(w.hours)r.push([String(w.fromHour).padStart(2,'0')+':00–'+String(w.toHour%24).padStart(2,'0')+':00','']);if(w.days)r.push([(w.weekdays||[]).map(x=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][x]).join('/'),'']);return r.map(([t,c])=>`<span class="status ${c}">${h(t)}</span>`).join(' ')||'—';};
 $('#radius-plans').innerHTML=table(['#','NAME','FOR','PRICE','SPEED (DOWN / UP)','VALIDITY','SESSIONS','DEVICE','RESTRICTIONS','CUSTOMERS','ACTIONS'],ordered,(p,i)=>`<tr><td class="pk-order"><b class="pk-n">${i+1}</b><button class="ra-btn" data-move-plan="${p.id}|-1" title="Move up" aria-label="Move up">▲</button><button class="ra-btn" data-move-plan="${p.id}|1" title="Move down" aria-label="Move down">▼</button></td><td><strong>${h(p.name)}</strong><small>${h((p.features||[]).slice(0,3).join(' · ')||p.description||'')}</small></td><td>${{pppoe:'PPPoE',hotspot:'Hotspot',both:'Both'}[p.service]}</td><td>${ksh(p.price)}</td><td>↓${p.downloadMbps} / ↑${p.uploadMbps} Mbps</td><td>${h(durationText(p))}</td><td>${p.maxSessions?'Max '+p.maxSessions:'No max'}<small>${p.devices} device${p.devices===1?'':'s'} per user</small></td><td>${(p.routerIds||[]).length?h((p.routerIds||[]).map(id=>(typeof rows==='function'?rows('devices'):[]).find(d=>d.id===id)?.name||'Removed router').join(', ')):'All'}</td><td>${tags(p)}</td><td>${d.subscribers.filter(s=>s.planId===p.id).length}</td><td><div class="row-actions ra"><button class="ra-btn ra-primary" data-edit-plan="${p.id}"><span>Edit</span></button><button class="ra-btn ra-danger" data-del-plan="${p.id}"><span>Delete</span></button></div></td></tr>`,'No packages yet. Create the packages you sell (e.g. 24 hrs unlimited, KSh 50).');
 for(const b of document.querySelectorAll('[data-move-plan]'))b.onclick=()=>{const [pid,dir]=b.dataset.movePlan.split('|');movePlan(pid,Number(dir));};}
 $('#radius-sessions').innerHTML=table(['SUBSCRIBER','TYPE','IP / MAC','ROUTER','STARTED','DOWNLOADED','UPLOADED'],d.sessions,s=>`<tr><td><strong>${h(s.username)}</strong></td><td>${s.service==='pppoe'?'PPPoE':s.service==='static'?'Static IP':'Hotspot'}</td><td>${h(s.ip||'—')}<small>${h(s.mac||'')}</small></td><td>${h(s.nas)}</td><td>${h(stamp(s.startedAt))}</td><td>${bytesShort(s.downloadBytes)}</td><td>${bytesShort(s.uploadBytes)}</td></tr>`,'Nobody is online through the netops RADIUS yet.');
 $('#radius-log').innerHTML=table(['TIME','LOGIN','TYPE','RESULT','REASON','ROUTER / MAC'],d.log,l=>`<tr><td>${h(stamp(l.time))}</td><td><code>${h(l.username)}</code></td><td>${l.service==='pppoe'?'PPPoE':l.service==='static'?'Static IP':'Hotspot'}</td><td><span class="status ${l.result==='accept'?'online':'offline'}">${l.result==='accept'?'Accepted':'Rejected'}</span></td><td>${h(l.reason)}</td><td>${h(l.nas)}<small>${h(l.mac||'')}</small></td></tr>`,'No login attempts yet.');
 paintBilling();paintMpesa();
 {const bf=$('#blocked-devs');if(bf){const list=d.settings.blockedMacs||[],paint=()=>{$('#blocked-list').innerHTML=list.length?table(['MAC','REASON','BY','WHEN',''],list,b=>`<tr><td><code>${h(b.mac)}</code></td><td>${h(b.reason||'—')}</td><td>${h(b.by||'')}</td><td>${h(stamp(b.at))}</td><td><button type="button" class="button secondary" data-unblock="${h(b.mac)}">Unblock</button></td></tr>`):'<p class="muted small">No blocked devices.</p>';for(const x of document.querySelectorAll('[data-unblock]'))x.onclick=async()=>{try{await api('radius/settings','PUT',{blockedMacs:list.filter(b=>b.mac!==x.dataset.unblock)});toast('Unblocked');await loadRadius();}catch(e){toast(e.message);}};};paint();
  bf.onsubmit=async e=>{e.preventDefault();try{await api('radius/settings','PUT',{blockedMacs:[...list,{mac:bf.mac.value,reason:bf.reason.value,by:state.session.user.name,at:Date.now()}]});toast('Device blocked');await loadRadius();}catch(err){toast(err.message);}};}}
 {const f=$('#acct-policy');if(f){f.deactivateAfterDays.value=d.settings.deactivateAfterDays||0;f.installFeeAmount.value=d.settings.installFeeAmount||0;f.installFeePppoe.checked=!!d.settings.installFeePppoe;f.strictRouter.checked=d.settings.roaming==='assigned';f.installFeeStatic.checked=!!d.settings.installFeeStatic;f.installFeeStaticAmount.value=d.settings.installFeeStaticAmount||0;f.usageMarginPct.value=d.settings.usageMarginPct||0;f.selfPackageChange.checked=d.settings.selfPackageChange!==false;f.onsubmit=async e=>{e.preventDefault();try{await api('radius/settings','PUT',{deactivateAfterDays:Number(f.deactivateAfterDays.value),installFeeAmount:Number(f.installFeeAmount.value),installFeePppoe:f.installFeePppoe.checked,roaming:f.strictRouter.checked?'assigned':'any',installFeeStatic:f.installFeeStatic.checked,installFeeStaticAmount:Number(f.installFeeStaticAmount.value),usageMarginPct:Number(f.usageMarginPct.value),selfPackageChange:f.selfPackageChange.checked});toast('Saved');await loadRadius();}catch(error){toast(error.message);}};}}
 {const f=$('#mac-binding');if(f){f.macBinding.value=d.settings.macBinding||'off';f.onsubmit=async e=>{e.preventDefault();try{await api('radius/settings','PUT',{macBinding:f.macBinding.value});toast('Saved');await loadRadius();}catch(error){toast(error.message);}};}}
 for(const el of document.querySelectorAll(".radius-realm"))el.textContent=d.settings.realm;
 for(const b of document.querySelectorAll('[data-radius-tab]'))b.classList.toggle('active',b.dataset.radiusTab===radiusView.tab);
 for(const p of document.querySelectorAll('[data-radius-panel]'))p.hidden=p.dataset.radiusPanel!==radiusView.tab;
 const on=(sel,fn)=>{for(const b of document.querySelectorAll(sel))b.onclick=()=>fn(Object.values(b.dataset)[0]);};
 on('[data-pay]',paySubscriber);on('[data-renew]',renewSubscriber);on('[data-edit-sub]',subscriberEditor);on('[data-pass]',revealPassword);on('[data-del-sub]',id=>removeRecord('subscribers',id,'this subscriber'));on('[data-edit-plan]',planEditor);on('[data-del-plan]',id=>removeRecord('plans',id,'this plan'));
}
async function loadRadius(){const request=++radiusView.request;try{const [d,b,m]=await Promise.all([api('radius'),api('billing'),api('mpesa')]);if(request!==radiusView.request||!(state.page==='radius'||window.radiusPreset?.(state.page)))return;radiusView.data=d;radiusView.billing=b;radiusView.mpesa=m;paintRadius();}catch(error){if(request===radiusView.request)$('#radius-content').innerHTML=notice('Could not load subscribers',h(error.message),true);}}
function renderRadius(){
 $('#main').innerHTML=heading('Subscribers & plans','Netops\' own RADIUS: who may log in, at what speed and until when. It replaces ISPman one router at a time.','<button class="button secondary" id="radius-import">Import CSV</button><button class="button secondary" id="radius-new-plan">New plan</button><button class="button primary" id="radius-new-sub">New subscriber</button>')+
 `<div id="radius-content"><div id="radius-metrics" class="dashboard-cards sites-cards radius-cards"><div class="card metric-card"><p>Loading…</p></div></div>
 <div class="sites-tabs" role="tablist">${[['subscribers','Subscribers'],['plans','Plans'],['sessions','Online now'],['log','Login log'],['payments','Payments'],['mpesa','M-Pesa & portal'],['sms','SMS'],['setup','Router setup']].map(([k,l])=>`<button type="button" role="tab" data-radius-tab="${k}">${l}</button>`).join('')}</div>
 <section class="card sites-panel" data-radius-panel="subscribers"><div class="table-toolbar sites-toolbar radius-toolbar"><input type="search" id="radius-query" placeholder="Search name, username, phone, MAC" aria-label="Search subscribers"><select id="radius-filter" aria-label="Status">${radiusOptions([['all','All subscribers'],['active','Active'],['online','Online now'],['expired','Expired'],['unpaid','Never paid'],['suspended','Deactivated']],radiusView.filter)}</select></div><div id="radius-subscribers"></div></section>
 <section class="card sites-panel" data-radius-panel="plans" hidden><div id="radius-plans"></div></section>
 <section class="card sites-panel" data-radius-panel="sessions" hidden><div class="card-header"><div><h2>Online now</h2><p>Sessions the routers reported in the last 15 minutes (accounting every 5 minutes).</p></div></div><div id="radius-sessions"></div></section>
 <section class="card sites-panel" data-radius-panel="log" hidden><div class="card-header"><div><h2>Login log</h2><p>Every login attempt and why it was accepted or rejected (latest 500).</p></div></div><div id="radius-log"></div></section>
 <section class="card sites-panel" data-radius-panel="payments" hidden><div class="card-header"><div><h2>Payments</h2><p>Each payment renews whole plan periods; any leftover stays as credit. A reference (M-Pesa code) is accepted once only.</p></div></div><div id="radius-payments"></div></section>
 <section class="sites-panel" data-radius-panel="mpesa" hidden><div id="radius-mpesa"></div></section>
 <section class="sites-panel" data-radius-panel="sms" hidden><div id="radius-sms"></div></section>
 <section class="card sites-panel" data-radius-panel="setup" hidden><div class="card-header"><div><h2>Connect a MikroTik</h2><p>Each router reaches this RADIUS through a private WireGuard tunnel to the netops server. Nothing here changes a router by itself.</p></div></div>
 <ol class="radius-steps"><li><strong>Once on the server:</strong> <code>sudo bash deployment/wireguard/setup-server.sh</code>, open UDP 51820 in Azure, set <code>RADIUS_SECRET</code> and <code>NETWORK_RADIUS_TOKEN</code> in <code>.env</code>, then <code>docker compose --profile radius up -d --build</code>.</li><li><strong>Per router:</strong> <code>sudo bash deployment/wireguard/add-router.sh hEX 2</code> prints the commands to paste on that MikroTik.</li><li><strong>Test without affecting customers:</strong> the router sends only logins ending in <code>@<span class="radius-realm"></span></code> to netops; everyone else stays on ISPman. Log in as <code>username@<span class="radius-realm"></span></code> on PPPoE or the hotspot.</li><li><strong>Switch over</strong> one router at a time once tests pass. ISPman stays as the fallback until you remove it.</li></ol><form id="acct-policy" class="radius-form"><h3>Account rules</h3><div class="form-grid"><label>Deactivate PPPoE after this many days expired (7–365, 0 = never)<input name="deactivateAfterDays" type="number" min="0" max="365"></label><label>Installation fee for new PPPoE customers (KSh)<input name="installFeeAmount" type="number" min="0" step="1"></label></div><label class="check-label"><input type="checkbox" name="installFeePppoe"> Charge the installation fee to new PPPoE customers</label><label class="check-label"><input type="checkbox" name="strictRouter"> Strict router assignment: customers with a router on their account may only log in through that router (off: their router follows wherever a PPPoE customer connects)</label><div class="form-grid"><label>Installation fee for new static customers (KSh)<input name="installFeeStaticAmount" type="number" min="0" step="1"></label><label>Network packets margin (%)<input name="usageMarginPct" type="number" min="0" max="100" step="0.1"></label></div><label class="check-label"><input type="checkbox" name="installFeeStatic"> Charge the installation fee to new static customers</label><label class="check-label"><input type="checkbox" name="selfPackageChange"> Customers can ask for another package from the WiFi / account page</label><p class="muted small">The margin covers retransmissions and protocol overhead: at 20%, 10 GB counted by the router is recorded as 12 GB for fair-usage caps and reports. It applies to new accounting from now on and never lowers usage; the router's own count is kept.</p><p class="muted small">Deactivated accounts are kept; a payment reactivates them. The fee is taken from the first payment before the package.</p><button class="button primary">Save account rules</button></form><form id="mac-binding" class="radius-form"><h3>Router MAC binding (PPPoE)</h3><p class="muted">When on, a PPPoE customer is tied to the first router that logs in (or the MAC you imported) and a different router is refused until you clear the binding on their record.</p><label>Binding<select name="macBinding"><option value="off">Off</option><option value="enforce">On: bind and enforce</option></select></label><button class="button primary">Save</button></form><form id="blocked-devs" class="radius-form"><h3>Blocked devices</h3><p class="muted">Phones, laptops or routers that may never log in (hotspot or PPPoE), whatever account they use: for abuse or stolen devices. Takes effect at the next login.</p><div class="form-grid"><label>MAC address<input name="mac" placeholder="AA:BB:CC:DD:EE:FF" required></label><label>Reason<input name="reason" maxlength="120"></label></div><button class="button primary">Block device</button><div id="blocked-list"></div></form></section></div>`;
 $('#radius-new-plan').onclick=()=>planEditor();$('#radius-import').onclick=importDialog;$('#radius-new-sub').onclick=()=>subscriberEditor();
 for(const b of document.querySelectorAll('[data-radius-tab]'))b.onclick=()=>{radiusView.tab=b.dataset.radiusTab;paintRadius();};
 $('#radius-query').oninput=e=>{radiusView.q=e.target.value;paintRadius();};$('#radius-filter').onchange=e=>{radiusView.filter=e.target.value;paintRadius();};
 loadRadius();
}
setInterval(()=>{if(state.session?.user&&(state.page==='radius'||window.radiusPreset?.(state.page))&&!document.hidden&&!$('dialog[open]'))loadRadius();},60000);

// Payments and SMS (server-side billing)
function paySubscriber(id){const s=radiusView.data.subscribers.find(x=>x.id===id),p=radiusView.data.plans.find(x=>x.id===s?.planId);if(!s||!p)return;
 radiusForm('Record payment — '+s.name,`${p.name}: ${ksh(p.price)} per ${durationText(p)}.${s.balance?' Current credit '+ksh(s.balance)+'.':''} Whole periods are added automatically; the rest stays as credit.`,
  `<div class="form-grid">${radiusField('Amount (KSh)',`<input name="amount" type="number" min="1" step="1" required value="${h(p.price)}">`)+radiusField('Method',`<select name="method">${radiusOptions([['mpesa','M-Pesa'],['cash','Cash'],['bank','Bank'],['other','Other']],'mpesa')}</select>`)}</div>`+radiusField('Reference (M-Pesa code or receipt number)',`<input name="reference" required maxlength="40" pattern="[A-Za-z0-9_\\-]{4,40}" placeholder="TJK1ABC2DE" autocomplete="off">`)+radiusField('Note (optional)','<input name="note" maxlength="200">'),
  'Record payment',async input=>{const r=await api('radius/subscribers/'+id+'/payments','POST',{...input,amount:Number(input.amount)});toast(r.periods?`Renewed ${r.periods} period${r.periods>1?'s':''}. Active until ${stamp(r.subscriber.expiresAt)}.${r.sms?' SMS '+r.sms.status+'.':''}`:`Saved as credit (${ksh(r.balance)}). Not enough for a full period yet.`);});}
// Message templates editor: one card per message with an on/off switch, the text, a reset to the default, variable
// chips that insert at the cursor, a live character / SMS-parts count, and optional wording per service.
const TPL_VARS={welcome:['name','fullname','username','plan','price','account','paybill','company'],payment:['name','fullname','amount','reference','plan','expiry','days_left','username','company'],reminder:['name','fullname','plan','price','expiry','days_left','paybill','account','username','company'],expired:['name','fullname','plan','price','paybill','account','username','company']};
const TPL_DESC={welcome:'Sent when staff add a customer (if switched on).',payment:'Sent after a payment renews or tops up an account.',reminder:'Sent before the package runs out, on the days set below.',expired:'Sent when the package has expired.'};
const smsParts=t=>{const n=t.length,uni=/[^\x00-\x7F]/.test(t),one=uni?70:160,many=uni?67:153;return n<=one?1:Math.ceil(n/many);};
function tplCard(k,label,name,value,{on,canOff,isAdmin,placeholder,def}){const vars=TPL_VARS[k]||[];
 return `<div class="tpl-card" data-tpl-card><div class="tpl-head"><div><b>${h(label)}</b><small>${h(TPL_DESC[k]||'')}</small></div>${canOff?`<label class="tpl-switch" title="Send this message"><input type="checkbox" name="on-${k}" ${on?'checked':''} ${isAdmin?'':'disabled'}><span></span></label>`:''}</div>
 <div class="tpl-box"><textarea name="${name}" rows="3" maxlength="459" ${isAdmin?'':'disabled'} ${placeholder?`placeholder="${h(placeholder)}"`:''} data-tpl-text>${h(value)}</textarea>${isAdmin&&def!=null?`<button type="button" class="tpl-reset" data-tpl-reset="${h(def)}" title="Reset to the default message" aria-label="Reset to the default message">↺</button>`:''}</div>
 <div class="tpl-foot"><div class="tpl-chips">${vars.map(v=>`<button type="button" class="tpl-chip" data-tpl-var="{${v}}" ${isAdmin?'':'disabled'}>{${v}}</button>`).join('')}</div><small class="tpl-count" data-tpl-count></small></div></div>`;}
function tplEditor(cfg,defaults,isAdmin,labels,SV){
 return `<section class="card tpl-section"><div class="card-header"><div><h2>Message templates</h2><p>The text of each automatic SMS. Click a variable to insert it where the cursor is.</p></div></div>
 <form id="sms-templates" class="radius-form tpl-form">${Object.keys(labels).map(k=>`${tplCard(k,labels[k],'t-'+k,cfg.templates[k],{on:cfg.enabled[k],canOff:true,isAdmin,def:defaults[k]})}
  <details class="tpl-more"><summary>Different wording for ${Object.values(SV).join(' / ')}</summary>${Object.entries(SV).map(([sv,sl])=>tplCard(k,sl+' — '+labels[k].toLowerCase(),'t-'+sv+'.'+k,cfg.templates[sv+'.'+k]||'',{canOff:false,isAdmin,placeholder:'Empty = same as the message above'})).join('')}</details>`).join('')}
 <div class="tpl-card"><div class="form-grid">${radiusField('Remind this many days before expiry',`<input name="reminderDays" value="${h(cfg.reminderDays.join(', '))}" ${isAdmin?'':'disabled'}>`)}</div></div>
 ${isAdmin?'<div class="tpl-save"><button class="button primary">Save messages</button></div>':''}</form></section>`;}
function wireTplEditor(){const f=$('#sms-templates');if(!f)return;let last=null;
 const count=ta=>{const c=ta.closest('[data-tpl-card]').querySelector('[data-tpl-count]'),t=ta.value;c.textContent=t?`${t.length}/459 · ${smsParts(t)} SMS`:'';c.classList.toggle('warn',smsParts(t)>1);};
 for(const ta of f.querySelectorAll('[data-tpl-text]')){count(ta);ta.addEventListener('input',()=>count(ta));ta.addEventListener('focus',()=>{last=ta;});}
 for(const b of f.querySelectorAll('[data-tpl-var]'))b.onclick=()=>{const ta=b.closest('[data-tpl-card]').querySelector('[data-tpl-text]');const v=b.dataset.tplVar,st=ta.selectionStart??ta.value.length,en=ta.selectionEnd??st;ta.value=ta.value.slice(0,st)+v+ta.value.slice(en);ta.focus();ta.setSelectionRange(st+v.length,st+v.length);count(ta);};
 for(const b of f.querySelectorAll('[data-tpl-reset]'))b.onclick=()=>{const ta=b.closest('[data-tpl-card]').querySelector('[data-tpl-text]');if(ta.value!==b.dataset.tplReset&&!confirm('Put back the default message?'))return;ta.value=b.dataset.tplReset;count(ta);ta.focus();};}
function paintBilling(){const b=radiusView.billing;if(!b)return;const sms=b.sms,cfg=b.settings,methods={mpesa:'M-Pesa',cash:'Cash',bank:'Bank',other:'Other'};
 $('#radius-payments').innerHTML=table(['TIME','SERVICE','CUSTOMER','AMOUNT','PROVIDER','REFERENCE','ROUTER','RENEWED','ACTIVE UNTIL'],b.payments,p=>`<tr><td>${h(stamp(p.time))}</td><td>${p.service?h(p.service==='pppoe'?'PPPoE':p.service==='static'?'Static':'Hotspot'):'—'}</td><td><strong>${h(p.name)}</strong><small>${h(p.username)}${p.phone?' · '+h(p.phone):''}</small></td><td>${p.reversedAt?`<s>${ksh(p.amount)}</s><small class="status offline">Reversed</small>`:ksh(p.amount)}</td><td>${h(p.provider||methods[p.method]||p.method)}</td><td><code>${h(p.reference)}</code>${p.note?`<small>${h(p.note)}</small>`:''}</td><td>${h(p.router||'—')}</td><td>${p.periods?p.periods+' period'+(p.periods>1?'s':''):'<span class="muted">Credit only</span>'}</td><td>${p.expiresAt?h(stamp(p.expiresAt)):'—'}</td></tr>`,'No payments recorded yet. Use Payment on a subscriber, or connect M-Pesa (coming next).');
 const isAdmin=state.session.user.role==='admin',labels={reminder:'Before expiry',expired:'On expiry',payment:'Payment received',welcome:'Welcome (when staff add a customer)'},SV={pppoe:'PPPoE',hotspot:'Hotspot',static:'Static IP'};
 $('#radius-sms').innerHTML=`<div class="radius-sms-grid"><section class="card"><div class="card-header"><div><h2>SMS provider</h2><p>${sms.config.configured?(sms.config.provider==='custom'?`Custom SMS API · <strong>${h(new URL(sms.config.url).host)}</strong>`:`Africa's Talking · <strong>${h(sms.config.username)}</strong>`)+`${sms.config.senderId?' · sender '+h(sms.config.senderId):''}${sms.config.sandbox?' · sandbox':''}`:"Not set up. Messages run on the server every 10 minutes (8 am – 8 pm), even with netops closed."}</p></div></div>
 ${isAdmin?`<form id="sms-config" class="radius-form">${(()=>{const c=sms.config,custom=c.provider!=='africastalking',f=c.fields||{apiKey:'api_key',senderId:'sender_id',phone:'phone',message:'message'},saved=c.configured?'Saved — leave empty to keep':'';return `${radiusField('Provider',`<select name="provider" id="sms-provider">${radiusOptions([['custom','Custom SMS API (e.g. BlessedTexts)'],['africastalking',"Africa's Talking"]],custom?'custom':'africastalking')}</select>`)}
 <div data-sms="custom" ${custom?'':'hidden'}>${radiusField('SMS API URL',`<input name="url" value="${h(c.url||'https://sms.blessedtexts.com/api/sms/v1/sendsms')}">`)}</div>
 <div data-sms="africastalking" ${custom?'hidden':''}>${radiusField("Africa's Talking username",`<input name="username" maxlength="60" value="${h(c.username||'')}">`)}</div>
 <div class="form-grid">${radiusField('Sender ID',`<input name="senderId" maxlength="15" value="${h(c.senderId||'')}" placeholder="Approved name">`)+radiusField('API key',`<input name="apiKey" type="password" maxlength="200" autocomplete="off" placeholder="${saved}">`)}</div>
 <details data-sms="custom" class="radius-advanced" ${custom?'':'hidden'}><summary>Advanced: request format (only if your provider's docs differ)</summary><div class="form-grid">${radiusField('Format',`<select name="format">${radiusOptions([['json','JSON'],['form','Form fields']],c.format||'json')}</select>`)+radiusField('Phone number as',`<select name="phoneFormat">${radiusOptions([['254','2547XXXXXXXX'],['+254','+2547XXXXXXXX'],['07','07XXXXXXXX']],c.phoneFormat||'254')}</select>`)+radiusField('API key field',`<input name="field_apiKey" value="${h(f.apiKey)}">`)+radiusField('Sender ID field',`<input name="field_senderId" value="${h(f.senderId)}">`)+radiusField('Phone field',`<input name="field_phone" value="${h(f.phone)}">`)+radiusField('Message field',`<input name="field_message" value="${h(f.message)}">`)}</div></details>
 <button class="button primary">Save provider</button>`;})()}</form>
 <form id="sms-test" class="radius-form"><div class="form-grid">${radiusField('Send a test to',`<input name="to" required placeholder="07…">`)}</div><button class="button secondary">Send test SMS</button></form>`:'<p class="muted radius-form">Only admins can change SMS settings.</p>'}</section>
 ${tplEditor(cfg,b.defaults||{},isAdmin,labels,SV)}</div>
 <section class="card" id="sms-lib"><div class="card-header"><div><h2>SMS templates</h2><p>Saved messages to pick from when you write an SMS. Placeholders work here too.</p></div>${['admin','manager'].includes(state.session.user.role)?'<button class="button primary" id="sms-lib-new">Add template</button>':''}</div><div id="sms-lib-list"><p class="muted" style="padding:0 18px">Loading…</p></div></section>
 <section class="card"><div class="card-header"><div><h2>SMS log</h2><p>Every message sent or attempted (latest 300).</p></div></div>${table(['TIME','SERVICE','CUSTOMER','PHONE NUMBER','TYPE','STATUS','MESSAGE'],sms.log,l=>`<tr><td>${h(stamp(l.time))}</td><td>${l.customer?h(l.customer.service==='pppoe'?'PPPOE':l.customer.service==='static'?'STATIC':'HOTSPOT'):'—'}</td><td>${l.customer?`<button class="link-button" data-sms-prof="${h(l.customer.id)}">${h(l.customer.username.toUpperCase())}</button><small>${h(l.customer.name)}</small>`:'—'}</td><td>${h(l.to)}</td><td>${h(l.kind)}</td><td><span class="status ${l.status==='sent'?'online':'offline'}">${l.status==='sent'?(l.channel==='whatsapp'?'Sent · WhatsApp':'Sent'):'Failed'}</span><small>${h(l.detail)}</small></td><td class="radius-message">${h(l.message)}</td></tr>`,'No messages yet.')}</section>`;
 const submit=(sel,fn)=>{const f=$(sel);if(f)f.onsubmit=async e=>{e.preventDefault();const btn=$('button',f);btn.disabled=true;try{await fn(Object.fromEntries(new FormData(f)));await loadRadius();}catch(error){toast(error.message);}finally{btn.disabled=false;}};};
 submit('#sms-config',v=>api('billing/sms','PUT',v).then(()=>toast('SMS provider saved')));const sel=$('#sms-provider');if(sel)sel.onchange=()=>{for(const el of document.querySelectorAll('[data-sms]'))el.hidden=el.dataset.sms!==sel.value;};
 submit('#sms-test',v=>api('billing/sms/test','POST',v).then(r=>toast((r.status==='sent'?'Test SMS sent. ':'Test failed. ')+r.detail)));
 {const can=['admin','manager'].includes(state.session.user.role),edit=t=>radiusForm(t?'Edit '+t.name:'New SMS template','Placeholders: {name} {plan} {price} {expiry} {username}.',`<label>Name<input name="name" maxlength="60" required value="${h(t?.name||'')}"></label><label>Category (optional)<input name="category" maxlength="40" value="${h(t?.category||'')}"></label><label>Message<textarea name="content" rows="5" maxlength="459" required>${h(t?.content||'')}</textarea></label><label class="check-label"><input type="checkbox" name="active" ${!t||t.active?'checked':''}> Active (offered when writing an SMS)</label>`,'Save',async v=>{await api(t?'sms-templates/'+t.id:'sms-templates',t?'PUT':'POST',{...v,active:v.active==='on'});toast('Template saved');});
  api('sms-templates').then(r=>{const el=$('#sms-lib-list');if(!el)return;el.innerHTML=table(['NAME','CATEGORY','MESSAGE','ACTIVE','CREATED',''],r.items,t=>`<tr><td><strong>${h(t.name)}</strong></td><td>${h(t.category||'—')}</td><td class="muted">${h(t.content.slice(0,90))}${t.content.length>90?'…':''}</td><td>${t.active?'<span class="status online">Yes</span>':'<span class="status offline">No</span>'}</td><td>${h(stamp(t.created))}</td><td>${can?`<button class="button secondary" data-sl-edit="${h(t.id)}">Edit</button> <button class="button secondary" data-sl-del="${h(t.id)}">Delete</button>`:''}</td></tr>`,'No templates yet.');
   for(const b of el.querySelectorAll('[data-sl-edit]'))b.onclick=()=>edit(r.items.find(t=>t.id===b.dataset.slEdit));for(const b of el.querySelectorAll('[data-sl-del]'))b.onclick=async()=>{if(!confirm('Delete this template?'))return;try{await api('sms-templates/'+b.dataset.slDel,'DELETE');toast('Deleted');await loadRadius();}catch(e){toast(e.message);}};}).catch(()=>{});
  const nb=$('#sms-lib-new');if(nb)nb.onclick=()=>edit(null);}
 wireTplEditor();
 submit('#sms-templates',v=>api('billing/settings','PUT',{reminderDays:v.reminderDays,templates:Object.fromEntries([...Object.keys(labels).map(k=>[k,v['t-'+k]]),...Object.keys(SV).flatMap(sv=>Object.keys(labels).map(k=>[sv+'.'+k,v['t-'+sv+'.'+k]||'']))]),enabled:Object.fromEntries(Object.keys(labels).map(k=>[k,v['on-'+k]==='on']))}).then(()=>toast('Messages saved')));
}

// M-Pesa (Daraja STK Push) and the hotspot captive portal
function paintMpesa(){const m=radiusView.mpesa;if(!m)return;let portalHost='netops.kadenetworks.com';try{portalHost=new URL(m.portalUrl).host;}catch{}const c=m.config,isAdmin=state.session.user.role==='admin',statusText={pending:'Waiting',paid:'Paid',failed:'Failed'};
 $('#radius-mpesa').innerHTML=`<div class="radius-sms-grid"><section class="card"><div class="card-header"><div><h2>M-Pesa (Daraja)</h2><p>${c.configured?`${c.env==='production'?'Live':'Sandbox (test)'} · ${c.type==='till'?'Till '+h(c.till)+' (store '+h(c.shortcode)+')':'Paybill '+h(c.shortcode)}`:'Not set up. Create an app at developer.safaricom.co.ke, go live with your paybill or till, then enter its keys here.'}</p></div></div>
 ${isAdmin?`<form id="mpesa-config" class="radius-form"><div class="form-grid">${radiusField('Environment',`<select name="env">${radiusOptions([['sandbox','Sandbox (testing)'],['production','Live']],c.env||'sandbox')}</select>`)+radiusField('Type',`<select name="type">${radiusOptions([['paybill','Paybill'],['till','Till (Buy Goods)']],c.type||'paybill')}</select>`)+radiusField('Paybill / store number',`<input name="shortcode" required inputmode="numeric" value="${h(c.shortcode||'')}">`)+radiusField('Till number (tills only)',`<input name="till" inputmode="numeric" value="${h(c.till||'')}">`)+radiusField('Consumer key',`<input name="consumerKey" type="password" autocomplete="off" placeholder="${c.configured?'Saved — leave empty to keep':''}">`)+radiusField('Consumer secret',`<input name="consumerSecret" type="password" autocomplete="off" placeholder="${c.configured?'Saved — leave empty to keep':''}">`)+radiusField('Passkey (Lipa na M-Pesa Online)',`<input name="passkey" type="password" autocomplete="off" placeholder="${c.configured?'Saved — leave empty to keep':''}">`)}</div><button class="button primary">Save M-Pesa</button><p class="muted">Payments are confirmed with Safaricom before any account is credited, and each M-Pesa code counts once.</p></form>`:'<p class="muted radius-form">Only admins can change M-Pesa settings.</p>'}</section>
 <section class="card"><div class="card-header"><div><h2>Hotspot portal</h2><p>Customers buy Wi-Fi or renew home internet here: <a href="${h(m.portalUrl)}" target="_blank" rel="noopener">${h(m.portalUrl)}</a></p></div></div>
 <div class="radius-form"><p class="muted">The landing page has <strong>9 designs</strong> (Classic, Spotlight, Split Screen, Minimal, Midnight, Christmas, Futuristic, Bento, Elegant). Open it with the design panel to switch design, colour, wording and sections.</p><a class="button primary" href="#captive">Open captive experience designer</a></div>
 ${isAdmin?`<form id="portal-config" class="radius-form"><div class="form-grid">${radiusField('Name shown to customers',`<input name="name" maxlength="40" value="${h(m.portal?.name||'')}" placeholder="Kade Networks">`)+radiusField('Help contact (phone or WhatsApp)',`<input name="support" maxlength="80" value="${h(m.portal?.support||'')}" placeholder="0712 345 678">`)}</div><button class="button secondary">Save portal</button></form>`:''}
 <ol class="radius-steps"><li>Mark hotspot packages as <em>Hotspot</em> or <em>Both</em> under Plans; they appear on the portal.</li><li>Download <a class="button secondary" href="/api/portal/hotspot-login.html">login.html</a> and upload it to the router's hotspot folder (WinBox → Files → <code>hotspot/</code>, replace <code>login.html</code>). Keep a copy of the old one.</li>
 <li>Let customers reach the portal before paying (paste on the router):<pre class="sites-setup">/ip hotspot walled-garden add dst-host=${h(portalHost)} comment="netops portal"
/ip hotspot walled-garden ip add dst-host=${h(portalHost)} action=accept comment="netops portal"</pre></li><li>The router must use the netops RADIUS for hotspot logins (Router setup tab).</li></ol></section></div>
 ${m.c2b?`<section class="card"><div class="card-header"><div><h2>Paybill payments</h2><p>Customers pay paybill <strong>${h(c.shortcode)}</strong> with their <strong>username as the account number</strong>; netops credits them and sends the SMS receipt. Anything it can't match waits below for you to assign.</p></div></div>
 <div class="radius-form"><p class="muted">${m.c2b.registration?`Safaricom registration: <strong>${m.c2b.registration.ok?'registered':'not accepted'}</strong> — ${h(m.c2b.registration.message)} (${h(stamp(m.c2b.registration.time))})`:'Not registered with Safaricom yet.'}</p>${isAdmin?'<button class="button secondary" id="c2b-register" type="button">Register paybill URLs with Safaricom</button>':''}
 <details class="radius-advanced"><summary>Addresses to give Safaricom if registering by hand</summary><pre class="sites-setup">Confirmation URL: ${h(m.c2b.urls.confirmation)}
Validation URL:   ${h(m.c2b.urls.validation)}</pre></details></div>
 ${table(['TIME','RECEIPT','AMOUNT','ACCOUNT TYPED','PAID BY','STATUS'],m.c2b.payments,p=>`<tr><td>${h(stamp(p.paidAt))}</td><td><code>${h(p.transId)}</code></td><td>${ksh(p.amount)}</td><td>${h(p.account||'—')}</td><td>${h(p.payer||'—')}</td><td>${p.status==='credited'?`<span class="status online">Credited</span><small>${h(p.username||'')}</small>`:`<span class="status warning">Needs assigning</span>${isAdmin||state.session.user.role==='manager'?`<select data-c2b-pick="${h(p.id)}"><option value="">Choose subscriber…</option>${radiusView.data.subscribers.map(s=>`<option value="${h(s.id)}">${h(s.name)} (${h(s.username)})</option>`).join('')}</select><button class="button ghost" data-c2b-assign="${h(p.id)}">Credit</button>`:''}`}</td></tr>`,'No paybill payments received yet.')}</section>`:''}
 <section class="card"><div class="card-header"><div><h2>Portal payments</h2><p>M-Pesa requests from the portal (latest 300).</p></div></div>${table(['TIME','PHONE','FOR','AMOUNT','STATUS','RECEIPT / REASON','ACCOUNT'],m.payments,p=>`<tr><td>${h(stamp(p.createdAt))}</td><td>${h(p.phone)}</td><td>${p.kind==='account'?'Home internet':'Wi-Fi'}<small>${h(p.planName)}</small></td><td>${ksh(p.amount)}</td><td><span class="status ${p.status==='paid'?'online':p.status==='failed'?'offline':'warning'}">${statusText[p.status]||h(p.status)}</span></td><td>${p.receipt?`<code>${h(p.receipt)}</code>`:`<small>${h(p.reason||'')}</small>`}</td><td>${h(p.username||'—')}${p.status!=='paid'&&isAdmin?`<button class="button ghost" data-recheck="${h(p.id)}">Check with Safaricom</button>`:''}</td></tr>`,'No portal payments yet.')}</section>`;
 for(const b of document.querySelectorAll('[data-recheck]'))b.onclick=async()=>{b.disabled=true;try{const r=await api('mpesa/payments/'+b.dataset.recheck+'/recheck','POST',{});toast(r.message);await loadRadius();}catch(error){toast(error.message);b.disabled=false;}};
const reg=$('#c2b-register');if(reg)reg.onclick=async()=>{reg.disabled=true;try{const r=await api('mpesa/c2b/register','POST',{});toast(r.ok?'Registered with Safaricom':'Safaricom said: '+r.message);await loadRadius();}catch(error){toast(error.message);reg.disabled=false;}};
 for(const b of document.querySelectorAll('[data-c2b-assign]'))b.onclick=async()=>{const sel=document.querySelector(`[data-c2b-pick="${b.dataset.c2bAssign}"]`);if(!sel.value)return toast('Choose a subscriber first');b.disabled=true;try{const r=await api('mpesa/c2b/'+b.dataset.c2bAssign+'/assign','POST',{subscriberId:sel.value});toast('Credited '+r.username);await loadRadius();}catch(error){toast(error.message);b.disabled=false;}};
const pf=$('#portal-config');if(pf)pf.onsubmit=async e=>{e.preventDefault();const btn=$('button',pf);btn.disabled=true;try{await api('mpesa?section=portal','PUT',Object.fromEntries(new FormData(pf)));toast('Portal saved');await loadRadius();}catch(error){toast(error.message);}finally{btn.disabled=false;}};
 const f=$('#mpesa-config');if(f)f.onsubmit=async e=>{e.preventDefault();const btn=$('button',f);btn.disabled=true;try{await api('mpesa','PUT',Object.fromEntries(new FormData(f)));toast('M-Pesa saved');await loadRadius();}catch(error){toast(error.message);}finally{btn.disabled=false;}};
}

// Import customers from a CSV (e.g. an ISPman export): preview, then save all or nothing.
function importDialog(){let csv='';
 radiusForm('Import subscribers','Columns (any order): name, username, password, phone, plan, expires (YYYY-MM-DD), service, static_ip. Plans must already exist with the same names. Existing usernames are updated.',
  radiusField('CSV file','<input name="file" type="file" accept=".csv,text/csv,text/plain" required>')+'<div id="import-preview"></div>','Preview',async input=>{
   if(!csv){csv=await input.file.text();}
   const commit=$('#editor-form [type=submit]').dataset.commit==='1',r=await api('radius/import','POST',{csv,commit});
   if(r.committed){toast(`Imported ${r.create} new and updated ${r.update} subscribers`);return;}
   $('#import-preview').innerHTML=`<p><strong>${r.create}</strong> new · <strong>${r.update}</strong> updated · <strong class="${r.errors?'form-error':''}">${r.errors} with problems</strong></p>`+table(['LINE','USERNAME','RESULT'],r.rows.slice(0,200),x=>`<tr><td>${x.line}</td><td>${h(x.username)}</td><td>${x.error?`<span class="form-error">${h(x.error)}</span>`:x.action==='create'?'New':'Update'}${x.expiresAt?` <small>expires ${h(stamp(x.expiresAt))}</small>`:''}</td></tr>`);
   const btn=$('#editor-form [type=submit]');if(!r.errors){btn.textContent='Import '+r.total+' subscribers';btn.dataset.commit='1';}else{btn.textContent='Preview again';delete btn.dataset.commit;csv='';}
   throw Object.assign(new Error(r.errors?'Fix the rows marked in red in your file, then choose it again. Nothing was saved.':'Check the preview, then import.'),{keepOpen:true});
  });
 $('#editor-form [type=submit]').dataset.commit='';
}
